import 'dart:convert'; import 'package:http/http.dart' as http; import '../core/agent_models.dart'; import 'tool.dart';
class HttpTool extends AgentTool {
  String get name=>'http'; String get description=>'طلبات HTTP مع سياسة Zion Agent.'; Map<String,dynamic> get parameters=>const {'method':'GET | POST | PUT | DELETE','url':'string','headers':'Map<String,String>','body':'dynamic'};
  Future<StepResult> execute(Map<String,dynamic> p) async {final u=Uri.tryParse(p['url']?.toString()??'');if(u==null||!{'http','https'}.contains(u.scheme))return StepResult.failure('رابط HTTP/HTTPS غير صالح.');final m=(p['method']?.toString()??'GET').toUpperCase();final h=Map<String,String>.from(p['headers']??const {});try{late http.Response r;switch(m){case 'GET':r=await http.get(u,headers:h);break;case 'POST':r=await http.post(u,headers:h,body:jsonEncode(p['body']));break;case 'PUT':r=await http.put(u,headers:h,body:jsonEncode(p['body']));break;case 'DELETE':r=await http.delete(u,headers:h);break;default:return StepResult.failure('HTTP method غير مدعوم.');}return StepResult.success('HTTP '+r.statusCode.toString(),data:{'status':r.statusCode,'body':r.body,'headers':r.headers});}catch(e){return StepResult.failure('فشل HTTP: '+e.toString());}}
}
